INSERT OR IGNORE INTO material_catalog (id,curricular_unit_id,lesson_id,material_kind,bibliography_format,title,description,file_name,mime_type,storage_backend,storage_key,storage_state,byte_size,checksum_sha256,verification_status,publication_status,public_access,source_id,page_note,version_group,version_number,is_recommended,created_at,updated_at) SELECT 'material-biblio-2627-ap11-nolte6-translation',cu.id,'lesson-neuro-ap11','bibliography','translation','Nolte’s The Human Brain — AP11 · Tradução','Bibliografia traduzida para AP11. 130 páginas e 61 figuras numeradas, distribuídas por 62 páginas de figuras.','AP11_Nolte_Bibliografia_Traduzida_2026-10-10.pdf','application/pdf','r2','materials/neuroanatomia/bibliografia/traducoes/2026-27/AP11_Nolte_Bibliografia_Traduzida_2026-10-10.pdf','ready',19728989,'a4c271b47f632fd8b1a5e99ab6c82ea658b8e063e4bffe10b15a9304465dfdb8','verified','published',0,'source-nolte-6','Nolte, 6.ª edição: pp. 305–316; 524–540; 415–425; 437–454.','biblio-2627-ap11-nolte6-translation',1,1,unixepoch()*1000,unixepoch()*1000 FROM curricular_units cu WHERE cu.code='NEURO' AND cu.active=1 AND EXISTS(SELECT 1 FROM material_sources WHERE id='source-nolte-6') AND EXISTS(SELECT 1 FROM material_lessons WHERE id='lesson-neuro-ap11');

INSERT OR IGNORE INTO material_catalog_lessons(material_id,lesson_id,relevance,sort_order) SELECT 'material-biblio-2627-ap11-nolte6-translation','lesson-neuro-ap11','primary',0 WHERE EXISTS(SELECT 1 FROM material_catalog WHERE id='material-biblio-2627-ap11-nolte6-translation');

INSERT INTO admin_audit_log(actor_user_id,action,details,created_at) SELECT id,'neuro_translation_published','{"batch":"approved-ap11-nolte-2026-10-10"}',unixepoch()*1000 FROM users WHERE status='active' AND commission_position='principal_admin' AND NOT EXISTS(SELECT 1 FROM admin_audit_log WHERE action='neuro_translation_published' AND details LIKE '%approved-ap11-nolte-2026-10-10%') LIMIT 1;
